const FIXTURE_JSON: &str = include_str!("fixtures/eclipse/moon_eclipse_orekit.json");

#[derive(Debug, Deserialize)]
struct FixtureSource {
    orekit: String,
    hipparchus: String,
    orekit_data_commit: String,
}

#[derive(Debug, Deserialize)]
struct EclipseCase {
    name: String,
    kind: String,
    earth_flattening: f64,
    sat_m: [f64; 3],
    sun_m: [f64; 3],
    moon_m: [f64; 3],
    lighting_earth: f64,
    lighting_moon: f64,
    lighting_earth_and_moon: f64,
    acceleration_m_s2: [f64; 3],
    earth_angles: [f64; 3],
    moon_angles: [f64; 3],
    mutual_angles: [f64; 3],
    reference_lighting_earth: String,
    reference_lighting_moon: String,
}

#[derive(Debug, Deserialize)]
struct EclipseFixture {
    _source: FixtureSource,
    sun_radius_m: f64,
    earth_radius_m: f64,
    moon_radius_m: f64,
    wgs84_flattening: f64,
    d_ref_m: f64,
    p_ref_n_m2: f64,
    cr: f64,
    area_to_mass_m2_kg: f64,
    constructed: Vec<EclipseCase>,
    de440: Vec<EclipseCase>,
}

fn load_fixture() -> EclipseFixture {
    serde_json::from_str(FIXTURE_JSON).expect("parse Orekit moon eclipse fixture")
}

fn to_km(v_m: [f64; 3]) -> [f64; 3] {
    [v_m[0] / M_PER_KM, v_m[1] / M_PER_KM, v_m[2] / M_PER_KM]
}

fn earth_model(flattening: f64) -> EarthShadowModel {
    if flattening == 0.0 {
        EarthShadowModel::Spherical
    } else {
        EarthShadowModel::Wgs84Oblate
    }
}

/// 16-point Gauss-Legendre nodes and weights on `[-1, 1]`.
const GL16_NODES: [f64; 8] = [
    0.095_012_509_837_637_44,
    0.281_603_550_779_258_9,
    0.458_016_777_657_227_37,
    0.617_876_244_402_643_8,
    0.755_404_408_355_003,
    0.865_631_202_387_831_8,
    0.944_575_023_073_232_6,
    0.989_400_934_991_649_9,
];

const GL16_WEIGHTS: [f64; 8] = [
    0.189_450_610_455_068_5,
    0.182_603_415_044_923_58,
    0.169_156_519_395_002_54,
    0.149_595_988_816_576_73,
    0.124_628_971_255_533_87,
    0.095_158_511_682_492_78,
    0.062_253_523_938_647_89,
    0.027_152_459_411_754_095,
];

/// Independent high-precision numerical quadrature of
/// `Area(D_S ∩ (D_E ∪ D_M)) / (pi * a^2)` using piecewise 16-point
/// Gauss-Legendre integration in `x ∈ [-a, a]` with a `sin^2` endpoint
/// substitution on every subinterval to remove `sqrt(r^2 - (x - cx)^2)`
/// derivative singularities at circle edges.
fn independent_union_shadow_quadrature(
    a: f64,
    b_e: f64,
    c_e: f64,
    b_m: f64,
    c_m: f64,
    cos_psi: f64,
    sin_psi: f64,
) -> f64 {
    let mx = c_m * cos_psi;
    let my = c_m * sin_psi;

    let mut breaks = vec![-a, a];
    for &(cx, r) in &[(c_e, b_e), (mx, b_m)] {
        for x in [cx - r, cx + r] {
            if x > -a && x < a {
                breaks.push(x);
            }
        }
    }
    // Pairwise circle-circle intersection x-coordinates (cancellation-free
    // when one radius is much larger than the other, e.g. Earth vs Sun/Moon).
    let circles = [(0.0, 0.0, a), (c_e, 0.0, b_e), (mx, my, b_m)];
    for i in 0..3 {
        for j in (i + 1)..3 {
            // Put the smaller circle first so `x1` and `along` stay small and
            // `x1 + along * ux` never cancels against a large Earth disc.
            let ((x1, y1, r1), (x2, y2, r2)) = if circles[i].2 <= circles[j].2 {
                (circles[i], circles[j])
            } else {
                (circles[j], circles[i])
            };
            let dx = x2 - x1;
            let dy = y2 - y1;
            let d = libm::hypot(dx, dy);
            if d > 0.0 && d < r1 + r2 && d > (r1 - r2).abs() {
                let along = ((d - r2) * (d + r2) + r1 * r1) / (2.0 * d);
                let h = ((r1 - along) * (r1 + along)).max(0.0).sqrt();
                let ux = dx / d;
                let uy = dy / d;
                let px = x1 + along * ux;
                for sign in [-1.0, 1.0] {
                    let ix = px - sign * h * uy;
                    if ix > -a && ix < a {
                        breaks.push(ix);
                    }
                }
            }
        }
    }
    breaks.sort_by(|u, v| u.total_cmp(v));
    breaks.dedup_by(|u, v| (*u - *v).abs() <= 1.0e-15 * a);

    let slice_len = |x: f64| -> f64 {
        let ys = ((a - x) * (a + x)).max(0.0).sqrt();
        let mut segs = [(0.0, 0.0); 2];
        let mut count = 0;

        let de = (x - c_e).abs();
        if de < b_e {
            let ye = ((b_e - de) * (b_e + de)).max(0.0).sqrt();
            let lo = (-ys).max(-ye);
            let hi = ys.min(ye);
            if hi > lo {
                segs[count] = (lo, hi);
                count += 1;
            }
        }
        let dm = (x - mx).abs();
        if dm < b_m {
            let ym = ((b_m - dm) * (b_m + dm)).max(0.0).sqrt();
            let lo = (-ys).max(my - ym);
            let hi = ys.min(my + ym);
            if hi > lo {
                segs[count] = (lo, hi);
                count += 1;
            }
        }
        match count {
            0 => 0.0,
            1 => segs[0].1 - segs[0].0,
            _ => {
                if segs[0].0 > segs[1].0 {
                    segs.swap(0, 1);
                }
                if segs[1].0 <= segs[0].1 {
                    segs[0].1.max(segs[1].1) - segs[0].0
                } else {
                    (segs[0].1 - segs[0].0) + (segs[1].1 - segs[1].0)
                }
            }
        }
    };

    // Map x-breakpoints to theta = acos(-x / a) in [0, pi], so x = -a cos(theta)
    // and sqrt(a^2 - x^2) = a sin(theta) has no branch point at x = ±a.
    // Integrate each smooth subinterval [ta, tb] split into 16 sub-panels using
    // u in [0, pi/2], theta = t0 + (t1 - t0) * sin^2(u), which also regularizes
    // Earth/Moon edge square-root singularities.
    let theta_breaks: Vec<f64> = breaks
        .iter()
        .map(|&x| libm::acos((-x / a).clamp(-1.0, 1.0)))
        .collect();
    const SUB_PANELS: usize = 16;
    let mut area = 0.0;
    for pair in theta_breaks.windows(2) {
        let ta = pair[0];
        let tb = pair[1];
        if tb <= ta {
            continue;
        }
        let half_u = std::f64::consts::FRAC_PI_4;
        for panel in 0..SUB_PANELS {
            let t0 = ta + (tb - ta) * (panel as f64) / (SUB_PANELS as f64);
            let t1 = ta + (tb - ta) * ((panel + 1) as f64) / (SUB_PANELS as f64);
            let span = t1 - t0;
            if span <= 0.0 {
                continue;
            }
            let mut sub = 0.0;
            for (&node, &weight) in GL16_NODES.iter().zip(GL16_WEIGHTS.iter()) {
                for sign in [-1.0, 1.0] {
                    let u = half_u * (1.0 + sign * node);
                    let s = libm::sin(u);
                    let theta = t0 + span * s * s;
                    let (sin_th, cos_th) = libm::sincos(theta);
                    let x = -a * cos_th;
                    let dx_du = a * sin_th * span * libm::sin(2.0 * u);
                    sub += weight * slice_len(x) * dx_du;
                }
            }
            area += half_u * sub;
        }
    }

    (area / (std::f64::consts::PI * a * a)).clamp(0.0, 1.0)
}

fn psi_cos_sin(sat: [f64; 3], sun: [f64; 3], moon: [f64; 3]) -> (f64, f64) {
    let to_sun = Vector3::from(sun) - Vector3::from(sat);
    let to_earth = -Vector3::from(sat);
    let to_moon = Vector3::from(moon) - Vector3::from(sat);
    let us = to_sun.normalize();
    let ue = to_earth.normalize();
    let um = to_moon.normalize();
    let de = ue - us * ue.dot(&us);
    let dm = um - us * um.dot(&us);
    if de.norm() > 0.0 && dm.norm() > 0.0 {
        let deu = de.normalize();
        let dmu = dm.normalize();
        (
            deu.dot(&dmu).clamp(-1.0, 1.0),
            deu.cross(&dmu).norm().min(1.0),
        )
    } else {
        (1.0, 0.0)
    }
}

#[test]
fn orekit_fixture_metadata_and_constants_match() {
    let fixture = load_fixture();
    assert_eq!(fixture._source.orekit, "13.1.10");
    assert_eq!(fixture._source.hipparchus, "4.0.3");
    assert!(
        fixture._source.orekit_data_commit.len() == 40
            && fixture
                ._source
                .orekit_data_commit
                .chars()
                .all(|c| c.is_ascii_hexdigit()),
        "orekit_data_commit must be a 40-char git SHA"
    );
    assert_eq!(fixture.sun_radius_m, IAU_2015_SOLAR_RADIUS_KM * M_PER_KM);
    assert_eq!(fixture.earth_radius_m, MEAN_EARTH_RADIUS_KM * M_PER_KM);
    assert_eq!(fixture.moon_radius_m, MOON_RADIUS_KM * M_PER_KM);
    assert_eq!(
        fixture.wgs84_flattening.to_bits(),
        WGS84_FLATTENING.to_bits()
    );
    assert_eq!(fixture.constructed.len(), 169);
    assert_eq!(fixture.de440.len(), 38);
}

#[test]
fn single_body_earth_and_moon_match_orekit_and_montenbruck_gill_reference() {
    let fixture = load_fixture();
    let all_cases = fixture.constructed.iter().chain(fixture.de440.iter());

    // Tolerance vs 40-digit Montenbruck & Gill reference: 1.17e-9.
    // Cause: Orekit 13.1.10's maskingRatio computes c^2 + a^2 - b^2 directly
    // (measured max 1.163e-9 on LEO Earth penumbra) and clamps acos inputs to
    // ±nextDown(1.0) on annular eclipses (measured max 8.408e-10 on Moon).
    const REF_TOL: f64 = 1.17e-9;

    // Tolerance vs Orekit 13.1.10 double-precision maskingRatio: 9.4e-15.
    // Cause: fixture metre -> km -> metre round-trip (measured max 9.326e-15
    // on lunar annular cases) and two-body (l_earth + 1) - 1 rounding on
    // Earth cases (measured max 1.110e-16 = 0.5 * EPSILON).
    const OREKIT_SINGLE_TOL: f64 = 9.4e-15;

    let mut max_earth_ref = 0.0_f64;
    let mut max_moon_ref = 0.0_f64;
    let mut max_earth_orekit = 0.0_f64;
    let mut max_moon_orekit = 0.0_f64;

    for case in all_cases {
        let sat = to_km(case.sat_m);
        let sun = to_km(case.sun_m);
        let moon = to_km(case.moon_m);
        let model = earth_model(case.earth_flattening);

        let lighting_moon = 1.0 - moon_shadow_fraction(sat, sun, moon).expect("valid moon case");
        let ref_moon: f64 = case
            .reference_lighting_moon
            .parse()
            .expect("parse reference_lighting_moon");
        let err_moon_ref = (lighting_moon - ref_moon).abs();
        let err_moon_orekit = (lighting_moon - case.lighting_moon).abs();
        max_moon_ref = max_moon_ref.max(err_moon_ref);
        max_moon_orekit = max_moon_orekit.max(err_moon_orekit);
        assert!(
            err_moon_ref <= REF_TOL,
            "{} ({}): moon lighting {:.16} vs 40-digit ref {:.16} (diff {:.3e})",
            case.name,
            case.kind,
            lighting_moon,
            ref_moon,
            err_moon_ref
        );
        assert!(
            err_moon_orekit <= OREKIT_SINGLE_TOL,
            "{} ({}): moon lighting {:.16} vs Orekit {:.16} (diff {:.3e})",
            case.name,
            case.kind,
            lighting_moon,
            case.lighting_moon,
            err_moon_orekit
        );

        // Place a non-occulting Moon opposite the Sun to isolate Earth-only
        // apparent-disc shadow through the combined entry point.
        let far_moon = [-sun[0] * 0.01, -sun[1] * 0.01, -sun[2] * 0.01];
        let lighting_earth = 1.0
            - shadow_fraction_with_model_and_moon(sat, sun, far_moon, model)
                .expect("valid earth case");
        let ref_earth: f64 = case
            .reference_lighting_earth
            .parse()
            .expect("parse reference_lighting_earth");
        let err_earth_ref = (lighting_earth - ref_earth).abs();
        let err_earth_orekit = (lighting_earth - case.lighting_earth).abs();
        max_earth_ref = max_earth_ref.max(err_earth_ref);
        max_earth_orekit = max_earth_orekit.max(err_earth_orekit);
        assert!(
            err_earth_ref <= REF_TOL,
            "{} ({}): earth lighting {:.16} vs 40-digit ref {:.16} (diff {:.3e})",
            case.name,
            case.kind,
            lighting_earth,
            ref_earth,
            err_earth_ref
        );
        assert!(
            err_earth_orekit <= OREKIT_SINGLE_TOL,
            "{} ({}): earth lighting {:.16} vs Orekit {:.16} (diff {:.3e})",
            case.name,
            case.kind,
            lighting_earth,
            case.lighting_earth,
            err_earth_orekit
        );
    }

    assert!(max_earth_ref <= 1.17e-9, "max_earth_ref={max_earth_ref:e}");
    assert!(max_moon_ref <= 8.41e-10, "max_moon_ref={max_moon_ref:e}");
    assert!(
        max_earth_orekit <= 0.5 * f64::EPSILON,
        "max_earth_orekit={max_earth_orekit:e}"
    );
    assert!(
        max_moon_orekit <= 9.4e-15,
        "max_moon_orekit={max_moon_orekit:e}"
    );
}

#[test]
fn combined_earth_and_moon_matches_orekit_where_valid_and_quadrature_everywhere() {
    let fixture = load_fixture();
    let all_cases = fixture.constructed.iter().chain(fixture.de440.iter());

    // Tolerance vs Orekit 13.1.10 where Orekit's mutual subtraction does not
    // fire (145 cases): 9.4e-15 (measured max 9.326e-15, caused solely by the
    // fixture's metre -> km -> metre round-trip).
    const OREKIT_DISJOINT_TOL: f64 = 9.4e-15;

    // Tolerance vs independent piecewise Gauss-Legendre quadrature across all
    // 207 cases: 1.17e-9 (measured max 1.163e-9, caused by Orekit's single-body
    // maskingRatio cancellation and ±nextDown(1.0) annular clamping).
    const QUAD_TOL: f64 = 1.17e-9;

    // Measured bounds on unclamped two-body shadow properties across the 207
    // fixture cases: overshoot 4.936e-13 (geo partial+partial), monotonicity
    // residual 2.098e-10 (leo_oblate partial+partial, difference between
    // Orekit's maskingRatio and the exact triple-disc area), subadditivity
    // residual 4.936e-13.
    const OVERSHOOT_BOUND: f64 = 5.0e-13;
    const MONO_TOL: f64 = 2.1e-10;
    const SUBADD_TOL: f64 = 5.0e-13;

    let mut orekit_checked = 0usize;
    let mut orekit_defect_cases = 0usize;
    let mut orekit_negative_cases = 0usize;
    let mut max_orekit_disjoint_diff = 0.0_f64;
    let mut max_quad_diff = 0.0_f64;

    for case in all_cases {
        let sat = to_km(case.sat_m);
        let sun = to_km(case.sun_m);
        let moon = to_km(case.moon_m);
        let model = earth_model(case.earth_flattening);

        let f_both =
            shadow_fraction_with_model_and_moon(sat, sun, moon, model).expect("combined shadow");
        let lighting_both = 1.0 - f_both;
        assert!(
            f_both.is_finite() && (-OVERSHOOT_BOUND..=1.0 + OVERSHOOT_BOUND).contains(&f_both),
            "{} ({}): shadow fraction out of bounds: {f_both}",
            case.name,
            case.kind
        );

        let f_moon = moon_shadow_fraction(sat, sun, moon).expect("moon shadow");
        let far_moon = [-sun[0] * 0.01, -sun[1] * 0.01, -sun[2] * 0.01];
        let f_earth =
            shadow_fraction_with_model_and_moon(sat, sun, far_moon, model).expect("earth shadow");
        assert!(
            f_both + MONO_TOL >= f_earth.max(f_moon),
            "{} ({}): combined shadow {f_both} < max({f_earth}, {f_moon})",
            case.name,
            case.kind
        );
        assert!(
            f_both - SUBADD_TOL <= (f_earth + f_moon).min(1.0),
            "{} ({}): combined shadow {f_both} > min(1, {f_earth} + {f_moon})",
            case.name,
            case.kind
        );

        // Independent quadrature on Orekit's angles and 3D position angle psi.
        let [c_e, b_e, a] = case.earth_angles;
        let [c_m, b_m, _] = case.moon_angles;
        let (cos_psi, sin_psi) = psi_cos_sin(sat, sun, moon);
        let f_quad = independent_union_shadow_quadrature(a, b_e, c_e, b_m, c_m, cos_psi, sin_psi);
        let quad_diff = (f_both - f_quad).abs();
        max_quad_diff = max_quad_diff.max(quad_diff);
        assert!(
            quad_diff <= QUAD_TOL,
            "{} ({}): combined shadow {:.16} vs independent quadrature {:.16} (diff {:.3e})",
            case.name,
            case.kind,
            f_both,
            f_quad,
            quad_diff
        );

        // Identify whether Orekit's buggy mutual-overlap subtraction triggered
        // using Orekit's exact tests: lighting_earth != 0.0, lighting_moon != 0.0,
        // lighting_moon != 1.0, and mutual sep < limb + occ - 1e-10.
        let [mut_sep, mut_limb, mut_occ] = case.mutual_angles;
        let orekit_subtracts_mutual = case.lighting_earth != 0.0
            && case.lighting_moon != 0.0
            && case.lighting_moon != 1.0
            && (mut_sep - mut_limb - mut_occ < -1.0e-10);

        if !orekit_subtracts_mutual {
            orekit_checked += 1;
            let diff = (lighting_both - case.lighting_earth_and_moon).abs();
            max_orekit_disjoint_diff = max_orekit_disjoint_diff.max(diff);
            assert!(
                diff <= OREKIT_DISJOINT_TOL,
                "{} ({}): lighting {:.16} vs Orekit {:.16} (diff {:.3e})",
                case.name,
                case.kind,
                lighting_both,
                case.lighting_earth_and_moon,
                diff
            );
        } else {
            orekit_defect_cases += 1;
            if case.lighting_earth_and_moon < 0.0 {
                orekit_negative_cases += 1;
            }
            // Confirm Orekit's own value is strictly below the true lighting
            // ratio because it subtracted |E ∩ M| / |S| instead of adding
            // |S ∩ E ∩ M| / |S|.
            assert!(
                case.lighting_earth_and_moon < lighting_both,
                "{} ({}): expected Orekit's subtracted ratio {:.16} < true {:.16}",
                case.name,
                case.kind,
                case.lighting_earth_and_moon,
                lighting_both
            );
        }
    }

    assert_eq!(orekit_checked, 145);
    assert_eq!(orekit_defect_cases, 62);
    assert_eq!(orekit_negative_cases, 53);
    assert!(max_orekit_disjoint_diff <= 9.4e-15);
    assert!(max_quad_diff <= 1.17e-9);
}

#[test]
fn srp_acceleration_with_moon_matches_orekit_on_non_overlapping_cases() {
    let fixture = load_fixture();
    let d_ref_km = fixture.d_ref_m / M_PER_KM;
    let base_srp = SolarRadiationPressure::with_pressure(
        fixture.cr,
        fixture.area_to_mass_m2_kg,
        fixture.p_ref_n_m2,
        d_ref_km,
    )
    .expect("valid SRP")
    .with_moon_eclipse(true);

    // Tolerance on the SRP acceleration normalized by full-sunlight SRP
    // magnitude: 9.4e-15 (measured max 9.313e-15). Both the lighting ratio and
    // cannonball SRP follow Orekit 13.1.10 operation for operation; the residual
    // comes only from the fixture's metre -> km -> metre round-trip and
    // `AREA * CR / MASS` vs `area_to_mass * CR`.
    const FULL_SRP_NORM_TOL: f64 = 9.4e-15;

    let mut checked = 0usize;
    for case in fixture.constructed.iter().chain(fixture.de440.iter()) {
        let [mut_sep, mut_limb, mut_occ] = case.mutual_angles;
        let orekit_subtracts_mutual = case.lighting_earth != 0.0
            && case.lighting_moon != 0.0
            && case.lighting_moon != 1.0
            && (mut_sep - mut_limb - mut_occ < -1.0e-10);
        if orekit_subtracts_mutual {
            continue;
        }

        let sat = Vector3::from(to_km(case.sat_m));
        let sun = Vector3::from(to_km(case.sun_m));
        let moon = Vector3::from(to_km(case.moon_m));
        let srp = base_srp.with_earth_shadow_model(earth_model(case.earth_flattening));
        let accel_m_s2 = srp
            .acceleration_with_sun_moon(sat, sun, moon)
            .expect("SRP acceleration")
            * M_PER_KM;
        let orekit_m_s2 = Vector3::from(case.acceleration_m_s2);
        let sat_to_sun_r2 = (sun - sat).norm_squared();
        let full_srp_m_s2 = fixture.p_ref_n_m2
            * (d_ref_km * d_ref_km / sat_to_sun_r2)
            * fixture.cr
            * fixture.area_to_mass_m2_kg;
        let norm_err = (accel_m_s2 - orekit_m_s2).norm() / full_srp_m_s2;
        assert!(
            norm_err <= FULL_SRP_NORM_TOL,
            "{} ({}): SRP err / full_srp {:.3e} > {:.3e}",
            case.name,
            case.kind,
            norm_err,
            FULL_SRP_NORM_TOL
        );
        checked += 1;
    }

    assert_eq!(checked, 145);
}

#[test]
fn srp_acceleration_with_moon_matches_quadrature_on_overlapping_cases() {
    let fixture = load_fixture();
    let d_ref_km = fixture.d_ref_m / M_PER_KM;
    let base_srp = SolarRadiationPressure::with_pressure(
        fixture.cr,
        fixture.area_to_mass_m2_kg,
        fixture.p_ref_n_m2,
        d_ref_km,
    )
    .expect("valid SRP")
    .with_moon_eclipse(true);

    // Tolerance on overlapping cannonball SRP acceleration normalized by
    // full-sunlight SRP: 8.5e-10 (measured max 8.416e-10, caused by Orekit's
    // single-body maskingRatio annular ±nextDown(1.0) clamping and
    // aE2 - alpha2^2 cancellation).
    const OVERLAP_SRP_TOL: f64 = 8.5e-10;

    let mut checked = 0usize;
    for case in fixture.constructed.iter().chain(fixture.de440.iter()) {
        let [mut_sep, mut_limb, mut_occ] = case.mutual_angles;
        let orekit_subtracts_mutual = case.lighting_earth != 0.0
            && case.lighting_moon != 0.0
            && case.lighting_moon != 1.0
            && (mut_sep - mut_limb - mut_occ < -1.0e-10);
        if !orekit_subtracts_mutual {
            continue;
        }

        let sat = to_km(case.sat_m);
        let sun = to_km(case.sun_m);
        let moon = to_km(case.moon_m);
        let srp = base_srp.with_earth_shadow_model(earth_model(case.earth_flattening));
        let accel_m_s2 = srp
            .acceleration_with_sun_moon(sat.into(), sun.into(), moon.into())
            .expect("overlapping SRP acceleration")
            * M_PER_KM;

        let [c_e, b_e, a] = case.earth_angles;
        let [c_m, b_m, _] = case.moon_angles;
        let (cos_psi, sin_psi) = psi_cos_sin(sat, sun, moon);
        let f_quad = independent_union_shadow_quadrature(a, b_e, c_e, b_m, c_m, cos_psi, sin_psi);
        let lighting_quad = 1.0 - f_quad;

        let sat_v = Vector3::from(sat);
        let sun_v = Vector3::from(sun);
        let s_hat = (sun_v - sat_v).normalize();
        let full_srp_m_s2 = fixture.p_ref_n_m2
            * (d_ref_km * d_ref_km / (sun_v - sat_v).norm_squared())
            * fixture.cr
            * fixture.area_to_mass_m2_kg;
        let expected_m_s2 = -full_srp_m_s2 * lighting_quad * s_hat;
        let norm_err = (accel_m_s2 - expected_m_s2).norm() / full_srp_m_s2;
        assert!(
            norm_err <= OVERLAP_SRP_TOL,
            "{} ({}): overlapping SRP err / full_srp {:.3e} > {:.3e}",
            case.name,
            case.kind,
            norm_err,
            OVERLAP_SRP_TOL
        );
        checked += 1;
    }

    assert_eq!(checked, 62);
}

#[test]
fn force_models_use_crate_sun_moon_ephemeris_during_2024_solar_eclipse() {
    // 2024-04-08 18:17:00 TDB (near greatest solar eclipse).
    // The force models take the Sun and Moon in GCRS from
    // `sun_moon_gcrs_at_tdb_seconds` at the state epoch; build the shadow axis
    // from the same vectors.
    let epoch_tdb_s = j2000_seconds(2024, 4, 8, 18, 17, 0.0);
    let bodies = sun_moon_gcrs_at_tdb_seconds(epoch_tdb_s).expect("sun_moon_gcrs_at_tdb_seconds");
    let sun_km = Vector3::from(to_km(bodies.sun));
    let moon_km = Vector3::from(to_km(bodies.moon));

    // Place a LEO satellite directly on the Moon-Sun line above Earth's sunlit
    // side so it sits inside the Moon's umbra/antumbra computed from the
    // crate's own Sun/Moon ephemeris.
    let axis = (moon_km - sun_km).normalize();
    // Point on the shadow axis at r = 7000 km on the dayside of Earth.
    let dot_m = moon_km.dot(&axis);
    let closest = moon_km - axis * dot_m;
    let perp2 = closest.norm_squared();
    assert!(
        perp2 < 6_371.0 * 6_371.0,
        "2024-04-08 eclipse shadow axis must intersect Earth (closest = {:.1} km)",
        perp2.sqrt()
    );
    let sat_pos_km = closest - axis * (7_000.0_f64 * 7_000.0 - perp2).sqrt();
    let state = CartesianState::new(epoch_tdb_s, sat_pos_km.into(), [0.0, 7.5, 0.0]);
    let ctx = PropagationContext::default();

    let srp_with_moon = SolarRadiationPressure::new(1.3, 0.02).expect("valid SRP");
    let srp_earth_only = srp_with_moon.with_moon_eclipse(false);
    let a_srp_earth = srp_earth_only
        .acceleration(&state, &ctx)
        .expect("earth-only SRP");
    let a_srp_moon = srp_with_moon
        .acceleration(&state, &ctx)
        .expect("moon-enabled SRP");
    assert!(a_srp_earth.norm() > 0.0);
    assert_eq!(a_srp_moon, Vector3::zeros());

    let erp_earth_only = EarthRadiationPressure::new(1.2, 0.011).expect("valid ERP");
    let erp_with_moon = erp_earth_only.with_moon_eclipse(true);
    let a_erp_earth = erp_earth_only
        .acceleration(&state, &ctx)
        .expect("earth-only ERP");
    let a_erp_moon = erp_with_moon
        .acceleration(&state, &ctx)
        .expect("moon-enabled ERP");
    assert!(a_erp_moon.norm() > 0.0);
    assert!(
        a_erp_moon.norm() < a_erp_earth.norm(),
        "lunar eclipse on Earth's surface must reduce dayside albedo acceleration"
    );
}
